rows=19; cols=16; grid=[[4]*cols for _ in range(rows)]; points={1:[(2,2),(4,14),(10,10),(17,9)],6:[(4,4),(6,6),(7,14),(15,2)]};
for color,ps in points.items():
 for r,c in ps:grid[r][c]=color
# connect aligned 1 pairs diagonal
for a in points[1]:
 for b in points[1]:
  dr=b[0]-a[0]; dc=b[1]-a[1]
  if dr and abs(dr)==abs(dc):
   sr=1 if dr>0 else -1; sc=1 if dc>0 else -1
   for i in range(abs(dr)+1): grid[a[0]+sr*i][a[1]+sc*i]=1
print(grid)

g=[[4]*16 for _ in range(19)]; ones=[(2,2),(4,14),(10,10),(17,9)]; six=[(4,4),(6,6),(7,14),(15,2)];
for r,c in ones:g[r][c]=1
for r,c in six:g[r][c]=6
# line between aligned 1 markers
for (r,c),(s,d) in [(ones[0],ones[2])]:
 for i in range(s-r+1):g[r+i][c+i]=1
# 6 lines slope -1
for r,c in six:
 for rr in range(19):
  cc=r+c-rr
  if 0<=cc<16:g[rr][cc]=6
print(g)

g=[[4]*16 for _ in range(19)]; orig6=[(4,4),(6,6),(7,14),(15,2)]; orig1=[(2,2),(4,14),(10,10),(17,9)];
for r,c in orig1:g[r][c]=1
for r,c in orig6:g[r][c]=6
for i in range(9):
 r,c=2+i,2+i
 if g[r][c]!=6:g[r][c]=1
# perpendicular lines through 6s lying on 1 diagonal
for r,c in [(4,4),(6,6)]:
 for rr in range(19):
  cc=r+c-rr
  if 0<=cc<16 and g[rr][cc]==4:g[rr][cc]=6
